        "ar": "لاحظ اللعب التمثيلي أو الخيالي التلقائي، بما فيه المكونات الجديدة والإبداعية والرمزية وتمثيل الأدوار. قيّم لعباً تمثيلياً أو خيالياً مختلفاً في 5 مناسبات للنقطة الكاملة، أو مناسبتين لنصف النقطة."
