        "ar": "1: يكرر الطفل سلوك لعب حركي كبير في محاولة للحصول على تأثير مرغوب في نشاطين مختلفين.\n0.5: يكرر الطفل سلوك لعب حركي كبير في محاولة للحصول على تأثير مرغوب في نشاط واحد."
