        "ar": "يوجّه تلقائياً إلى الأقران سؤال WH خمس مرات (مثل: إلى أين تذهب؟ ما هذا؟ أي شخصية تمثل؟). (ملاحظة محددة الزمن: 60 دقيقة.)"
