      "examples": {
        "en": "When presented with an \"R\" and the verbal prompt, \"What letter is this?\" the child says \"R.\"",
        "ar": "عند عرض الحرف R وتقديم التلميح اللفظي «ما هذا الحرف؟»، يقول الطفل «R»."
      },
