    "w3-14": {
      "application": {
        "en": "Ask the child to write his own name without copying. Check independent writing, correct spelling and readability to another person; neatness is not required. Use half credit for letter approximations that are not clear enough to read and/or misspelling.",
        "ar": "اطلب من الطفل كتابة اسمه دون نسخ. تحقّق من الاستقلال في الكتابة وصحة التهجئة وإمكانية قراءته من شخص آخر؛ لا يُشترط ترتيب الخط. امنح نصف نقطة لتقريبات الحروف غير الواضحة بما يكفي للقراءة و/أو التهجئة الخاطئة."
      },
      "scoring": {
        "en": "1 point: Give the child 1 point if he independently and legibly writes and correctly spells his own name (\"legible\" does not need to be neat, this will come with practice).\n½ point: Give the child ½ point if he approximates the letters in his name, but they are not clear enough to read, and/or he misspells his name.",
        "ar": "1: امنح الطفل نقطة واحدة إذا كتب اسمه باستقلال وبصورة مقروءة وتهجّاه بصورة صحيحة. لا يُشترط أن تكون الكتابة المقروءة مرتبة؛ فهذا يتحسن بالممارسة.\n0.5: امنح الطفل نصف نقطة إذا قرّب حروف اسمه لكنها لم تكن واضحة بما يكفي للقراءة، و/أو أخطأ في تهجئة اسمه."
      },
      "allowHalf": true,
      "sourcePages": [
        94
      ],
      "text": {
        "en": "Legibly spells and writes his own name without copying. (T)",
        "ar": "يتهجّى ويكتب اسمه بصورة مقروءة دون نسخ. (T)"
      },
      "objective": {
        "en": "To determine if the child can write his own name, and that it is legible by a second party.",
        "ar": "تحديد ما إذا كان الطفل يستطيع كتابة اسمه بصورة يستطيع شخص آخر قراءتها."
      },
      "materials": {
        "en": "Any type of writing instrument (e.g., crayon, marker, chalk, pencil) and related surface (e.g., paper, whiteboard, or Magna Doodle).",
        "ar": "أي نوع من أدوات الكتابة، مثل قلم شمعي أو قلم تعليم أو طبشور أو قلم رصاص، وسطح مناسب، مثل الورق أو اللوح الأبيض أو لوحة Magna Doodle."
      },
      "examples": {
        "en": "The child will write his name on a lined piece of paper.",
        "ar": "يكتب الطفل اسمه على ورقة مسطرة."
      },
      "contentSource": "User-supplied Writing Level III text, 2026-10-29"
    },
