        "ar": "عند وجود عدة ألعاب على الطاولة، يقول البالغ «أعطني القبعة»، فيختار الطفل القبعة بنجاح من المجموعة. أو عند وجود عدة أشخاص في الغرفة، يقول البالغ «أين العم جو؟»، فينظر الطفل مباشرة إليه أو يتجه نحوه."
