        "ar": "1: ينجح الطفل باستقلال في وضع 3 أشياء في وعاء، أو تكديس 3 مكعبات، أو وضع 3 حلقات على وتد، أو ما يشابه ذلك، في أي نشاطين أثناء الملاحظة أو الاختبار.\n0.5: يضع الطفل شيئين في وعاء، أو يكدّس مكعبين، أو يضع حلقتين على وتد، أو ما يشابه ذلك، في أي نشاط واحد أثناء الملاحظة أو الاختبار."
