        "ar": "قدّم أشياء أو ألعاباً أو صوراً متطابقة أو أحاجي إدخال للمطابقة. لاحظ ما إذا كان الطفل يختار المطابق بصرياً ولديه المهارات الحركية الدقيقة لإكمال المهمة باستقلال. يمكن استخدام بعض التلميحات اللفظية والمعززات المرتبة خصيصاً كما يرد في الهدف."
