        "ar": "يُعرض على الطفل مجسم لسبونج بوب، فيختار مجسماً ثانياً مطابقاً له من مجموعة صغيرة من المجسمات. ويضع الطفل قطعة أحجية عليها كرة زرقاء في أحجية إدخال تحتوي في إطارها على صورة خلفية تطابق الكرة الزرقاء على القطعة."
