        "ar": "1: ينخرط الطفل باستقلال في حركة استكشافية ولمس في منطقة لعب جديدة لمدة دقيقتين خلال ملاحظة مدتها 30 دقيقة.\n0.5: ينخرط الطفل باستقلال في حركة استكشافية ولمس في منطقة لعب جديدة لمدة دقيقة واحدة خلال ملاحظة مدتها 30 دقيقة."
