        "ar": "1: يشير الطفل إلى رغبته في أن يُحمل أو يُلعب معه جسدياً مرتين خلال ملاحظة مدتها ساعة واحدة.\n0.5: يشير الطفل إلى رغبته في أن يُحمل أو يُلعب معه جسدياً مرة واحدة خلال ملاحظة مدتها ساعة واحدة."
